WITH scored AS (SELECT *, LEAD(cost) OVER (PARTITION BY category ORDER BY stock_qty, id) AS next_cost, LAG(cost) OVER (PARTITION BY category ORDER BY stock_qty, id) AS prev_cost, LAG(price) OVER (PARTITION BY category ORDER BY stock_qty, id) AS prev_price, LEAD(price) OVER (PARTITION BY category ORDER BY stock_qty, id) AS next_price, ROW_NUMBER() OVER (PARTITION BY category ORDER BY stock_qty, id) AS row_seq FROM products WHERE YEAR(launch_date) >= 2023) SELECT category, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, COUNT(DISTINCT id) AS distinct_ids FROM scored GROUP BY category HAVING distinct_ids >= 1 ORDER BY category DESC NULLS FIRST
